                    sum_b_total = lb + rb
                    if sum_a_total == 0 and sum_b_total == 0:
                        continue
                    total_cost = lc + rc
                    if total_cost < min_cost:
                        min_cost = total_cost

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

